import{_ as a,o as t,c as o,ag as d}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/commands.md","filePath":"modules/corelib/commands.md","lastUpdated":null}'),c={name:"modules/corelib/commands.md"};function i(l,e,n,s,r,p){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiCoreLib 的主命令是 <code>/emakicorelib</code>，别名为 <code>/corelib</code>、<code>/emakicore</code>。这些命令主要面向服务器管理员，用于重载 CoreLib、执行配置预检、查看或执行已注册 Action，以及排查循环 Action 任务。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/corelib reload</code></td><td>重载 CoreLib 配置与 Action 系统；预检失败时取消本次重载并保留旧配置。</td><td><code>emakicorelib.reload</code> 或 <code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib check [module|report|--fix]</code></td><td>执行配置预检、检查指定模块或查看最近一次报告；当前版本的 <code>--fix</code> 为只读提示，不执行自动修复。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action list</code></td><td>列出当前已注册 Action 的 id、category、source、owner、execution mode 与参数名。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action run &lt;actionId&gt; key=value ...</code></td><td>直接执行一条当前已注册的 Action；也支持 <code>/corelib action &lt;actionId&gt; key=value ...</code> 简写。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug all [on|off|status]</code></td><td>运行时切换全局 Debug 开关；不带参数等同 <code>status</code>。重载后恢复为 <code>debug.global_all</code> 的配置值。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug loops [list|player|key|cancel|cancel-player]</code></td><td>查看活动循环 Action 任务，并按 key 或玩家取消循环任务。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib help</code></td><td>显示子命令帮助；不带参数或输入未知子命令时也会显示。</td><td>无</td></tr></tbody></table><p><code>action</code> 子命令可写作 <code>actions</code>，两者等价。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicorelib.reload</code></td><td>op</td><td>允许重载 CoreLib。</td></tr><tr><td><code>emakicorelib.admin</code></td><td>op</td><td>CoreLib 管理员总权限，包含 <code>emakicorelib.reload</code>。</td></tr></tbody></table><h2 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h2><h3 id="重载-corelib" tabindex="-1">重载 CoreLib <a class="header-anchor" href="#重载-corelib" aria-label="Permalink to &quot;重载 CoreLib&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib reload</span></span></code></pre></div><p>适合修改 CoreLib 主配置、语言文件或 Action 后使用。重载会先执行配置预检；预检失败时不会替换当前正在生效的配置。</p><h3 id="执行配置预检" tabindex="-1">执行配置预检 <a class="header-anchor" href="#执行配置预检" aria-label="Permalink to &quot;执行配置预检&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib check</span></span>
<span class="line"><span>/corelib check report</span></span>
<span class="line"><span>/corelib check corelib</span></span></code></pre></div><p><code>check</code> 会检查配置引用、Action 模板、物品源与 CoreLib 相关配置。<code>report</code> 查看最近一次预检结果；传入模块 ID 时只检查指定模块。</p><h3 id="查看和执行已注册-action" tabindex="-1">查看和执行已注册 Action <a class="header-anchor" href="#查看和执行已注册-action" aria-label="Permalink to &quot;查看和执行已注册 Action&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib action list</span></span>
<span class="line"><span>/corelib action run sendmessage text=&quot;hello&quot;</span></span></code></pre></div><p><code>action list</code> 用来确认当前注册表里有哪些 Action。<code>action run</code> 会把 <code>&lt;actionId&gt; key=value ...</code> 按普通 Action 行解析，因此参数、引号、<code>@if</code>、<code>@chance</code>、<code>@delay</code> 等规则与配置文件中的 Action 行一致。控制台执行时没有玩家上下文，依赖玩家的 Action 会按既有 Action 校验失败。</p><h3 id="排查循环-action" tabindex="-1">排查循环 Action <a class="header-anchor" href="#排查循环-action" aria-label="Permalink to &quot;排查循环 Action&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib debug loops list</span></span>
<span class="line"><span>/corelib debug loops player Steve</span></span>
<span class="line"><span>/corelib debug loops key some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel-player Steve</span></span></code></pre></div><p>这些命令只用于排查或清理循环 Action。生产服上不建议长期保留大量循环任务调试输出。</p><h3 id="切换全局-debug" tabindex="-1">切换全局 Debug <a class="header-anchor" href="#切换全局-debug" aria-label="Permalink to &quot;切换全局 Debug&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/corelib debug all status</span></span>
<span class="line"><span>/corelib debug all on</span></span>
<span class="line"><span>/corelib debug all off</span></span></code></pre></div><p>作用等同于临时改写 <code>config.yml</code> 的 <code>debug.global_all</code>，会影响所有使用 CoreLib <code>DebugLogger</code> 的 Emaki 模块。该切换不写回配置文件，<code>/corelib reload</code> 后重新采用配置值。</p>`,23)])])}const u=a(c,[["render",i]]);export{h as __pageData,u as default};
